-- Dealer import (27.06.2026): replaces ALL dealers (users_group_id = 2).
-- Set the two category ids below to the right existing categories BEFORE running.
-- Back up first. Run in phpMyAdmin / mysql with the target database selected.
SET NAMES utf8mb4;
SET @cat_dpg = 1;  -- Diamond/Platinum/Gold file -> 1 = Air Coolers   (change if wrong)
SET @cat_sd  = 2;  -- Surround & Duet file          -> 2 = Tower/Cooling Fans (change if wrong)

-- add users.dealer_type if missing
SET @has := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'users' AND COLUMN_NAME = 'dealer_type');
SET @sql := IF(@has = 0, 'ALTER TABLE users ADD COLUMN dealer_type VARCHAR(50) NULL', 'SELECT 1');
PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;

DROP TABLE IF EXISTS dealer_import;
CREATE TABLE dealer_import (
  sympark_id INT NULL, name VARCHAR(255), address TEXT, town VARCHAR(150), district VARCHAR(150),
  state VARCHAR(150), zipcode VARCHAR(20), latitude DOUBLE NULL, longitude DOUBLE NULL, mobile VARCHAR(15),
  dealer_type VARCHAR(50) NULL, in_dpg TINYINT, in_sd TINYINT, city_name VARCHAR(150)
) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

