-- file spellings -> names already in the `states` table
UPDATE dealer_import SET state = 'Andaman and Nicobar Islands' WHERE state = 'Andaman & Nicobar Islands';
UPDATE dealer_import SET state = 'Dadra and Nagar Haveli' WHERE state = 'Dadra & Nagar Haveli';
UPDATE dealer_import SET state = 'Delhi' WHERE state = 'Nct Of Delhi';
UPDATE dealer_import SET state = 'Pondicherry' WHERE state = 'Puducherry';

START TRANSACTION;

DELETE FROM dealer_category WHERE dealer_id IN (SELECT id FROM users WHERE users_group_id = 2);
DELETE FROM users WHERE users_group_id = 2;

SET @country := (SELECT id FROM countries WHERE name = 'India' LIMIT 1);

-- states missing from the table (none expected after the mapping above)
SELECT DISTINCT i.state, @country FROM dealer_import i
WHERE i.state <> '' AND NOT EXISTS (SELECT 1 FROM states s WHERE s.name = i.state);

-- cities missing for that state
SELECT DISTINCT i.city_name, sm.id FROM dealer_import i
JOIN (SELECT name, MIN(id) AS id FROM states GROUP BY name) sm ON sm.name = i.state
WHERE i.city_name <> '' AND NOT EXISTS (SELECT 1 FROM cities c WHERE c.name = i.city_name AND c.state_id = sm.id);

SELECT i.name, NULL, '', i.mobile, 2, i.address, @country, cm.id, sm.id, i.zipcode, i.latitude, i.longitude, i.sympark_id, i.dealer_type, 1, NOW(), NOW()
FROM dealer_import i
LEFT JOIN (SELECT name, MIN(id) AS id FROM states GROUP BY name) sm ON sm.name = i.state
LEFT JOIN (SELECT name, state_id, MIN(id) AS id FROM cities GROUP BY name, state_id) cm ON cm.name = i.city_name AND cm.state_id = sm.id;

-- category links (sympark_id is unique per dealer in the import)
SELECT u.id, @cat_dpg FROM users u JOIN dealer_import i ON u.sympark_id = i.sympark_id WHERE u.users_group_id = 2 AND i.in_dpg = 1;
SELECT u.id, @cat_sd FROM users u JOIN dealer_import i ON u.sympark_id = i.sympark_id WHERE u.users_group_id = 2 AND i.in_sd = 1;

COMMIT;
DROP TABLE dealer_import;
